import{_ as e,o as t,c as o,ah as r}from"./chunks/framework.BdHuibk5.js";const _=JSON.parse('{"title":"山城游","description":"2016 年 11 月 18 到 21 号，四天重庆。周五下午三点半到江北机场，轻轨换到小什字住下，当晚就去了解放碑、洪崖洞和千厮门大桥。后面几天川美、十八梯、山城步道、磁器口、南山一棵树、长江索道走了一圈，周一三点回杭。","frontmatter":{"title":"山城游","date":"2016-11-21T00:00:00.000Z","category":"travel","tags":["旅行"],"slug":"chongqing-travel","layout":"blog-post","description":"2016 年 11 月 18 到 21 号，四天重庆。周五下午三点半到江北机场，轻轨换到小什字住下，当晚就去了解放碑、洪崖洞和千厮门大桥。后面几天川美、十八梯、山城步道、磁器口、南山一棵树、长江索道走了一圈，周一三点回杭。"},"headers":[],"relativePath":"blog/chongqing-travel.md","filePath":"blog/posts/travel/chongqing-travel.md","lastUpdated":1789387639000}'),l={name:"blog/chongqing-travel.md"};function n(i,a,p,s,c,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<p>2016 年 11 月 18 到 21 号，去了趟重庆，四天。山城到底怎么个山法，走一走就知道了。</p><p>出发前大致想过一圈：解放碑、小什字、朝天门、长江索道、十八梯、山城步道、重庆大礼堂、皇冠大扶梯、洪崖洞、重大虎溪、磁器口、南山一棵树、川美黄桷坪……真正走下来，顺序全乱了，有的去了两遍，有的干脆没去成。</p><h2 id="周五" tabindex="-1">周五 <a class="header-anchor" href="#周五" aria-label="Permalink to &quot;周五&quot;">​</a></h2><p>下午三点半到江北机场，坐轻轨 3 号线换乘 6 号线，到小什字下车，找到青旅。收拾好就步行去解放碑逛了逛，接着直往洪崖洞，在千厮门大桥拍了几张，再转回小什字，回到青旅。</p><p>第一晚就把夜景的名头先过了一遍。</p><h2 id="周六" tabindex="-1">周六 <a class="header-anchor" href="#周六" aria-label="Permalink to &quot;周六&quot;">​</a></h2><p>八点出门，先去了四川美术学院黄桷（jue）坪校区。然后方所书店、十八梯、山城步道、重庆大礼堂、皇冠大扶梯，一路走下来，腿已经不太是自己的了。</p><p>后来去了赵二火锅总店吃火锅，接着朝天门码头和广场，一路走回青旅。</p><h2 id="周日" tabindex="-1">周日 <a class="header-anchor" href="#周日" aria-label="Permalink to &quot;周日&quot;">​</a></h2><p>重庆大学虎溪校区，又转到川美那边。中午在熙街吃饭，李晓同请的。下午她带我们去磁器口逛，跟河坊街一个性质。</p><p>晚上南山一棵树看夜景，下来又去解放碑逛了逛。</p><h2 id="周一" tabindex="-1">周一 <a class="header-anchor" href="#周一" aria-label="Permalink to &quot;周一&quot;">​</a></h2><p>上午去坐长江索道，然后转车去重庆邮电大学。回到上新街道，一路走到下浩正街，走回青旅。</p><p>三点坐轻轨去机场，回杭。</p>',14)])])}const g=e(l,[["render",n]]);export{_ as __pageData,g as default};
